// Renders three tag clouds - JavaScript libraries, browser APIs and external web
// APIs used by each tool - from tags.json
// (generated by build_tags.py). Clicking a tag lists the tools that use it.
const container = document.getElementById('tags');
const HASH_PREFIX = '#api=';

const el = (tag, props = {}, children = []) => {
  const node = document.createElement(tag);
  Object.assign(node, props);
  node.append(...children);
  return node;
};

const formatDate = (value) => {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    return '';
  }
  return date.toLocaleDateString(undefined, {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
  });
};

const addStyles = () => {
  const style = document.createElement('style');
  style.textContent = `
    #tags { margin: 1.5rem 0 2rem; }
    .api-tag-section { margin-bottom: 2rem; }
    .api-tag-section h2 { margin: 0 0 0.25rem; }
    .api-tags-intro { color: #666; font-size: 0.9em; margin: 0 0 0.75rem; }
    .api-tag-cloud {
      display: flex;
      flex-wrap: wrap;
      align-items: baseline;
      justify-content: center;
      gap: 0.5rem 0.6rem;
      list-style: none;
      margin: 0;
      padding: 0;
    }
    .api-tag {
      font: inherit;
      line-height: 1.2;
      color: #0066cc;
      background: #f3f5fb;
      border: 1px solid #d9dce6;
      border-radius: 999px;
      padding: 0.3em 0.8em;
      cursor: pointer;
    }
    .api-tag:hover { border-color: #0066cc; }
    .api-tag[aria-pressed="true"] {
      background: #604881;
      border-color: #604881;
      color: white;
    }
    .api-tag-count { font-size: 0.75em; opacity: 0.7; margin-left: 0.3em; }
    .api-tag-results { margin-top: 1rem; }
    .api-tag-results h3 { margin: 0 0 0.5rem; }
    .api-tag-results ul { list-style: none; margin: 0; padding: 0; }
    .api-tag-results li {
      padding: 0.6em 0;
      border-bottom: 1px solid #eee;
    }
    .api-tag-results li:last-child { border-bottom: none; }
    .api-tool-name { font-weight: 600; }
    .api-tool-meta { color: #666; font-size: 0.85em; margin-left: 0.4em; }
    .api-tool-summary { color: #444; font-size: 0.9em; margin-top: 0.25em; }
  `;
  document.head.append(style);
};

const SECTIONS = [
  { kind: 'library', id: 'javascript-libraries', title: 'JavaScript libraries', intro: 'Libraries loaded from a CDN by two or more tools.' },
  { kind: 'browser-api', id: 'browser-apis', title: 'browser APIs', intro: 'Web platform features used by each tool\'s own code.' },
  { kind: 'web-api', id: 'web-apis', title: 'web APIs', intro: 'External services that tools talk to over the network.' },
];

const renderTools = (data, tag) => {
  const list = el('ul');
  for (const toolSlug of tag.tools) {
    const tool = data.tools[toolSlug];
    if (!tool) {
      continue;
    }
    const item = el('li', {}, [
      el('span', { className: 'api-tool-name' }, [
        el('a', { href: tool.url, textContent: toolSlug }),
      ]),
      el('span', { className: 'api-tool-meta' }, [
        `${formatDate(tool.created)} (`,
        el('a', { href: tool.colophon, textContent: 'about' }),
        ')',
      ]),
    ]);
    if (tool.summary) {
      const summary = el('div', {
        className: 'api-tool-summary',
        textContent: tool.summary,
      });
      if (tool.truncated) {
        summary.append(' ', el('a', { href: tool.colophon, textContent: '...' }));
      }
      item.append(summary);
    }
    list.append(item);
  }
  const noun = tag.count === 1 ? 'tool' : 'tools';
  return [el('h3', { textContent: `${tag.label}: ${tag.count} ${noun}` }), list];
};

const render = (data) => {
  const byTag = new Map(data.tags.map((tag) => [tag.tag, tag]));
  const buttons = new Map();
  // Each cloud shows its results directly beneath itself
  const resultsByKind = new Map();

  const showTag = (slug) => {
    const tag = byTag.get(slug);
    buttons.forEach((button, key) => {
      button.setAttribute('aria-pressed', String(key === slug && Boolean(tag)));
    });
    resultsByKind.forEach((results) => results.replaceChildren());
    if (tag && resultsByKind.has(tag.kind)) {
      resultsByKind.get(tag.kind).append(...renderTools(data, tag));
    }
  };

  const sections = [];
  for (const { kind, id, title, intro } of SECTIONS) {
    const tags = data.tags
      .filter((tag) => tag.kind === kind)
      .sort((a, b) => a.label.localeCompare(b.label));
    if (!tags.length) {
      continue;
    }
    // Font sizes are scaled within each cloud
    const counts = tags.map((tag) => Math.log(tag.count));
    const min = Math.min(...counts);
    const range = Math.max(...counts) - min || 1;
    const cloud = el('ul', { className: 'api-tag-cloud' });
    for (const tag of tags) {
      const scale = (Math.log(tag.count) - min) / range;
      const button = el('button', { type: 'button', className: 'api-tag' }, [
        tag.label,
        el('span', { className: 'api-tag-count', textContent: tag.count }),
      ]);
      button.style.fontSize = `${(0.8 + scale * 0.7).toFixed(2)}em`;
      button.setAttribute('aria-pressed', 'false');
      button.addEventListener('click', () => {
        const selected = button.getAttribute('aria-pressed') === 'true';
        // Selecting a tag stores it in the URL so the list can be linked to
        history.replaceState(
          null,
          '',
          selected ? location.pathname + location.search : HASH_PREFIX + tag.tag,
        );
        showTag(selected ? null : tag.tag);
      });
      buttons.set(tag.tag, button);
      cloud.append(el('li', {}, [button]));
    }
    const results = el('div', { className: 'api-tag-results' });
    results.setAttribute('aria-live', 'polite');
    resultsByKind.set(kind, results);
    sections.push(
      el('section', { id, className: 'api-tag-section' }, [
        el('h2', { textContent: `Browse by ${title}` }),
        el('p', { className: 'api-tags-intro', textContent: `${intro} Select a tag to list its tools.` }),
        cloud,
        results,
      ]),
    );
  }

  const fromHash = () =>
    location.hash.startsWith(HASH_PREFIX)
      ? decodeURIComponent(location.hash.slice(HASH_PREFIX.length))
      : null;

  container.replaceChildren(...sections);
  window.addEventListener('hashchange', () => showTag(fromHash()));
  showTag(fromHash());

  // The browser tried to scroll to the URL #fragment before the clouds were
  // rendered, when #tags was still empty and the section ids did not
  // exist. Now that they do, scroll to whatever the fragment points at.
  const selected = byTag.get(fromHash());
  let target = null;
  if (selected) {
    target = resultsByKind.get(selected.kind)?.closest('section');
  } else if (location.hash.length > 1) {
    const element = document.getElementById(decodeURIComponent(location.hash.slice(1)));
    if (element && container.contains(element)) {
      target = element;
    }
  }
  if (target) {
    target.scrollIntoView();
  }
};

if (container) {
  fetch(new URL('tags.json', import.meta.url))
    .then((response) => {
      if (!response.ok) {
        throw new Error(`tags.json returned ${response.status}`);
      }
      return response.json();
    })
    .then((data) => {
      addStyles();
      render(data);
    })
    .catch((error) => {
      // The tag cloud is optional: leave the page as it is if tags.json is missing
      console.warn('Could not load API tags', error);
    });
}
